# -*- coding: utf-8 -*-
# GENERADO por herramientas_pc/generar_motor_fuente.py: no lo cambies a mano.
MOTOR = '# -*- coding: utf-8 -*-\n"""\nmotor_juegos_kira.py - Motor de JUEGOS 2D de Kira (lógica PURA: no dibuja, no usa Kivy; solo math y random).\n\nPara programar un juego:\n    from motor_juegos_kira import Juego\n\n    class MiJuego(Juego):\n        titulo = "Mi juego"\n        def preparar(self):                 # al empezar (y al reiniciar)\n            self.nave = self.rect(170, 40, 40, 20, "azul")\n        def actualizar(self, dt):           # 60 veces por segundo; dt = segundos desde el anterior\n            if self.dedo:                   # (x, y) donde está tocando el dedo, o None\n                self.nave.x = self.dedo[0] - self.nave.w / 2\n        def al_tocar(self, x, y):           # un toque\n            pass\n\nCoordenadas: el juego mide self.ancho x self.alto (360 x 640 por defecto), con (0, 0) ABAJO a la izquierda.\nLa pantalla de juegos lo escala para que quepa en cualquier móvil.\nPiezas: rect(), circulo(), texto(), linea(), poligono(); cada una tiene x, y, w, h (o r), vx, vy, color y viva.\n  linea(x1, y1, x2, y2, color, grosor): un segmento. poligono([(x, y), ...], color): figura rellena (mejor convexa);\n  sus puntos se guardan respecto a su centro, así se mueve con vx/vy y gira con girar(p, grados).\nIMÁGENES (gráficos realistas pintados por Kira): imagen(x, y, w, h, "nombre") dibuja el dibujo «nombre» de la\n  carpeta del juego (atributo sprites = "mi_juego"). Qué hay que pintar se dice en el atributo dibujos:\n      dibujos = {"jugador": "a knight in shiny armor", "fondo": "a medieval castle courtyard"}\n  y «Kira, pinta los dibujos del juego» los pinta (los personajes, sin fondo). Si aún no están, sale un recuadro.\nFísica: con vx/vy se mueven solas; self.gravedad tira hacia abajo de las que tengan cae=True.\nAyudas: chocan(a, b), rebotar_en_bordes(e), dentro(e), azar(a, b), fin("mensaje"), ganar("mensaje").\n"""\nimport math\nimport random\n\nCOLORES = {\n    "blanco": (1, 1, 1), "negro": (0.08, 0.08, 0.1), "gris": (0.55, 0.58, 0.62), "rojo": (0.92, 0.26, 0.3),\n    "verde": (0.2, 0.78, 0.45), "azul": (0.2, 0.5, 0.95), "cian": (0.0, 0.78, 1.0), "amarillo": (1.0, 0.82, 0.2),\n    "naranja": (1.0, 0.55, 0.15), "rosa": (1.0, 0.35, 0.72), "morado": (0.6, 0.35, 0.95), "marron": (0.55, 0.35, 0.2),\n}\nMAX_PIEZAS = 2000\n\n\ndef color(c):\n    """\'rojo\' | (r, g, b) | (r, g, b, a) -> (r, g, b, a) con valores de 0 a 1."""\n    if isinstance(c, str):\n        r, g, b = COLORES.get(c.lower(), COLORES["blanco"])\n        return (r, g, b, 1.0)\n    t = tuple(float(v) for v in c)\n    if len(t) == 3:\n        t = t + (1.0,)\n    if len(t) != 4:\n        raise ValueError("color: usa un nombre o (r, g, b) entre 0 y 1")\n    return tuple(max(0.0, min(1.0, v)) for v in t)\n\n\nclass Pieza:\n    def __init__(self, forma, x, y, w=0.0, h=0.0, col="blanco", texto="", tam=24):\n        self.forma = forma                  # \'rect\' | \'circulo\' | \'texto\' | \'linea\' | \'poligono\'\n        self.x, self.y, self.w, self.h = float(x), float(y), float(w), float(h)\n        self.vx = self.vy = 0.0\n        self.color = color(col)\n        self.texto, self.tam = str(texto), int(tam)\n        self.viva = True\n        self.cae = False                    # ¿le afecta la gravedad?\n        self.datos = {}                     # para lo que quieras guardar en ella\n        self.puntos = []                    # línea y polígono: [(dx, dy)] respecto a (x, y)\n        self.grosor = 2.0\n\n    # para círculos: (x, y) es el CENTRO y r el radio\n    @property\n    def r(self):\n        return self.w / 2.0\n\n    @r.setter\n    def r(self, v):\n        self.w = self.h = 2.0 * float(v)\n\n    def caja(self):\n        """(izquierda, abajo, derecha, arriba)"""\n        if self.forma in ("linea", "poligono") and self.puntos:\n            xs = [self.x + dx for dx, _ in self.puntos]\n            ys = [self.y + dy for _, dy in self.puntos]\n            return (min(xs), min(ys), max(xs), max(ys))\n        if self.forma == "circulo":\n            return (self.x - self.r, self.y - self.r, self.x + self.r, self.y + self.r)\n        return (self.x, self.y, self.x + self.w, self.y + self.h)\n\n    @property\n    def centro(self):\n        if self.forma in ("circulo", "poligono"):\n            return (self.x, self.y)\n        return (self.x + self.w / 2.0, self.y + self.h / 2.0)\n\n\ndef chocan(a, b):\n    """¿Se tocan dos piezas? (círculo-círculo exacto; el resto, por cajas)."""\n    if not (a.viva and b.viva):\n        return False\n    if a.forma == b.forma == "circulo":\n        return math.hypot(a.x - b.x, a.y - b.y) <= a.r + b.r\n    if "circulo" in (a.forma, b.forma):\n        c, r = (a, b) if a.forma == "circulo" else (b, a)\n        x1, y1, x2, y2 = r.caja()\n        px, py = max(x1, min(c.x, x2)), max(y1, min(c.y, y2))\n        return math.hypot(c.x - px, c.y - py) <= c.r\n    a1, b1, a2, b2 = a.caja()\n    c1, d1, c2, d2 = b.caja()\n    return a1 < c2 and c1 < a2 and b1 < d2 and d1 < b2\n\n\nFORMAS = ("rect", "circulo", "texto", "linea", "poligono", "imagen")\n\n\nclass Juego:\n    titulo = "Juego"\n    instrucciones = ""\n    sprites = ""                  # carpeta de sus dibujos pintados (gráficos realistas)\n    dibujos = {}                  # {"nombre": "descripción en inglés para pintarlo"} ("fondo": el escenario)\n    ancho, alto = 360, 640\n    fondo = (0.97, 0.98, 1.0)\n\n    def __init__(self, semilla=None):\n        self.azar_gen = random.Random(semilla)\n        self.reiniciar()\n\n    # ---------- lo que programas tú ----------\n    def preparar(self):\n        pass\n\n    def actualizar(self, dt):\n        pass\n\n    def al_tocar(self, x, y):\n        pass\n\n    def al_soltar(self, x, y):\n        pass\n\n    def al_deslizar(self, dx, dy):\n        """Deslizar el dedo: dx, dy en unidades del juego (útil para la serpiente)."""\n        pass\n\n    # ---------- motor ----------\n    def reiniciar(self):\n        self.piezas = []\n        self.puntos = 0\n        self.vidas = 3\n        self.estado = "jugando"             # \'jugando\' | \'fin\' | \'ganado\' | \'pausa\'\n        self.mensaje = ""\n        self.tiempo = 0.0\n        self.gravedad = 0.0\n        self.dedo = None\n        self.preparar()\n\n    def paso(self, dt):\n        """Un fotograma. La pantalla lo llama ~60 veces por segundo."""\n        dt = max(0.0, min(float(dt), 0.05))\n        if self.estado != "jugando":\n            return\n        self.tiempo += dt\n        self.actualizar(dt)\n        for p in self.piezas:\n            if p.cae:\n                p.vy -= self.gravedad * dt\n            if p.vx or p.vy:\n                if p.forma == "circulo":\n                    p.x += p.vx * dt\n                    p.y += p.vy * dt\n                else:\n                    p.x += p.vx * dt\n                    p.y += p.vy * dt\n        self.piezas = [p for p in self.piezas if p.viva]\n\n    def tocar(self, x, y):\n        if self.estado in ("fin", "ganado"):\n            self.reiniciar()\n            return\n        self.dedo = (x, y)\n        if self.estado == "jugando":\n            self.al_tocar(x, y)\n\n    def mover_dedo(self, x, y, dx=0.0, dy=0.0):\n        self.dedo = (x, y)\n        if self.estado == "jugando" and (dx or dy):\n            self.al_deslizar(dx, dy)\n\n    def soltar(self, x, y):\n        self.dedo = None\n        if self.estado == "jugando":\n            self.al_soltar(x, y)\n\n    def pausar(self):\n        if self.estado == "jugando":\n            self.estado = "pausa"\n        elif self.estado == "pausa":\n            self.estado = "jugando"\n\n    # ---------- piezas ----------\n    def _nueva(self, p):\n        if len(self.piezas) >= MAX_PIEZAS:\n            raise RuntimeError(f"demasiadas piezas (máximo {MAX_PIEZAS}): borra las que ya no uses (p.viva = False)")\n        self.piezas.append(p)\n        return p\n\n    def rect(self, x, y, w, h, col="blanco"):\n        return self._nueva(Pieza("rect", x, y, w, h, col))\n\n    def circulo(self, x, y, r, col="blanco"):\n        return self._nueva(Pieza("circulo", x, y, 2 * r, 2 * r, col))\n\n    def texto(self, x, y, texto, tam=24, col="negro"):\n        return self._nueva(Pieza("texto", x, y, 0, 0, col, texto=texto, tam=tam))\n\n    def imagen(self, x, y, w, h, nombre, col="blanco"):\n        """Un dibujo pintado (ver «dibujos»). (x, y) es la esquina de abajo a la izquierda, como en rect()."""\n        return self._nueva(Pieza("imagen", x, y, w, h, col, texto=str(nombre)))\n\n    def linea(self, x1, y1, x2, y2, col="negro", grosor=2):\n        p = Pieza("linea", x1, y1, 0, 0, col)\n        p.puntos, p.grosor = [(0.0, 0.0), (float(x2) - x1, float(y2) - y1)], max(0.5, float(grosor))\n        return self._nueva(p)\n\n    def poligono(self, puntos, col="azul"):\n        pts = [(float(x), float(y)) for x, y in puntos]\n        if len(pts) < 3:\n            raise ValueError("poligono: hacen falta al menos 3 puntos")\n        if len(pts) > 64:\n            raise ValueError("poligono: máximo 64 puntos")\n        cx, cy = sum(x for x, _ in pts) / len(pts), sum(y for _, y in pts) / len(pts)\n        p = Pieza("poligono", cx, cy, 0, 0, col)\n        p.puntos = [(x - cx, y - cy) for x, y in pts]\n        return self._nueva(p)\n\n    @staticmethod\n    def mover_linea(l, x1, y1, x2, y2):\n        """Cambia los extremos de una línea ya creada (para animar sin crear piezas nuevas)."""\n        l.x, l.y = float(x1), float(y1)\n        l.puntos = [(0.0, 0.0), (float(x2) - l.x, float(y2) - l.y)]\n\n    @staticmethod\n    def poner_puntos(p, puntos):\n        """Cambia la forma de un polígono ya creado (puntos en la pantalla)."""\n        pts = [(float(x), float(y)) for x, y in puntos][:64]\n        if len(pts) >= 3:\n            p.x, p.y = sum(x for x, _ in pts) / len(pts), sum(y for _, y in pts) / len(pts)\n            p.puntos = [(x - p.x, y - p.y) for x, y in pts]\n\n    @staticmethod\n    def girar(p, grados):\n        """Gira una línea o un polígono sobre su centro (o sobre su primer punto, la línea)."""\n        a = math.radians(grados)\n        c, s_ = math.cos(a), math.sin(a)\n        p.puntos = [(dx * c - dy * s_, dx * s_ + dy * c) for dx, dy in p.puntos]\n\n    def borrar(self, p):\n        p.viva = False\n\n    def con_etiqueta(self, nombre):\n        return [p for p in self.piezas if p.viva and p.datos.get("tipo") == nombre]\n\n    # ---------- ayudas ----------\n    chocan = staticmethod(chocan)\n\n    def dentro(self, p):\n        x1, y1, x2, y2 = p.caja()\n        return x2 > 0 and x1 < self.ancho and y2 > 0 and y1 < self.alto\n\n    def rebotar_en_bordes(self, p, suelo=True):\n        """Rebota en las paredes y el techo (y en el suelo si suelo=True). Devuelve qué borde tocó o \'\'."""\n        x1, y1, x2, y2 = p.caja()\n        borde = ""\n        if x1 < 0 and p.vx < 0:\n            p.vx, borde = -p.vx, "izquierda"\n        if x2 > self.ancho and p.vx > 0:\n            p.vx, borde = -p.vx, "derecha"\n        if y2 > self.alto and p.vy > 0:\n            p.vy, borde = -p.vy, "arriba"\n        if y1 < 0 and p.vy < 0:\n            if suelo:\n                p.vy = -p.vy\n            borde = "abajo"\n        return borde\n\n    def limitar(self, p):\n        """Que no se salga de la pantalla."""\n        x1, y1, x2, y2 = p.caja()\n        if x1 < 0:\n            p.x -= x1\n        if x2 > self.ancho:\n            p.x -= x2 - self.ancho\n        if y1 < 0:\n            p.y -= y1\n        if y2 > self.alto:\n            p.y -= y2 - self.alto\n\n    def azar(self, a, b):\n        return self.azar_gen.uniform(a, b)\n\n    def azar_entero(self, a, b):\n        return self.azar_gen.randint(a, b)\n\n    def fin(self, mensaje="Fin de la partida"):\n        self.estado, self.mensaje = "fin", str(mensaje)\n\n    def ganar(self, mensaje="¡Has ganado!"):\n        self.estado, self.mensaje = "ganado", str(mensaje)\n\n    # ---------- lo que dibuja la pantalla ----------\n    def dibujo(self):\n        """[(forma, x, y, w, h, (r,g,b,a), texto, tam, puntos)] en coordenadas del juego.\n        puntos: línea/polígono, [(x, y)] ya colocados en la pantalla (y en la línea, tam = grosor)."""\n        return [(p.forma, p.x, p.y, p.w, p.h, p.color, p.texto,\n                 p.grosor if p.forma == "linea" else p.tam,\n                 [(p.x + dx, p.y + dy) for dx, dy in p.puntos]) for p in self.piezas if p.viva]\n\n    def marcador(self):\n        base = f"Puntos: {self.puntos}   Vidas: {self.vidas}"\n        if self.estado == "pausa":\n            return base + "   (pausa)"\n        if self.estado in ("fin", "ganado"):\n            return f"{self.mensaje}  —  {self.puntos} puntos. Toca para jugar otra vez."\n        return base\n\n\ndef buscar_juego(globales):\n    """La clase de juego que define un programa (la última subclase de Juego), o None."""\n    candidatas = [v for v in globales.values() if isinstance(v, type) and issubclass(v, Juego) and v is not Juego]\n    return candidatas[-1] if candidatas else None\n'
